@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400;1,700&family=Inter:wght@300;400;500;600&display=swap');

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-bg: #F5F2ED;
  --color-text: #1A1A1A;
  --color-text-light: #6B6560;
  --color-accent-terracotta: #C4705A;
  --color-accent-sage: #8B9E7E;
  --color-accent-sand: #D4B896;
  --color-border: #D6D1CB;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1400px;
  --page-padding: clamp(24px, 5vw, 80px);
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-weight: 400;
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.7;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* ── Header / Navigation ── */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 28px var(--page-padding);
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--color-bg);
  transition: background-color 0.3s ease;
}

.site-logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.site-logo a {
  transition: opacity 0.2s ease;
}

.site-logo a:hover {
  opacity: 0.6;
}

.desktop-nav {
  display: flex;
  gap: 36px;
}

.desktop-nav a {
  font-size: 0.875rem;
  font-weight: 400;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  transition: opacity 0.2s ease;
}

.desktop-nav a:hover {
  opacity: 0.5;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  background: none;
  border: none;
  cursor: pointer;
  position: relative;
  z-index: 1100;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 1.5px;
  background-color: var(--color-text);
  transition: all 0.3s ease;
}

.hamburger span:nth-child(1) {
  margin-bottom: 6px;
}

.hamburger span:nth-child(2) {
  margin-bottom: 0;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(2.5px, 2.5px);
}

.hamburger.active span:nth-child(2) {
  transform: rotate(-45deg) translate(2.5px, -2.5px);
}

.mobile-overlay {
  position: fixed;
  inset: 0;
  background-color: var(--color-bg);
  z-index: 1050;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 40px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-overlay.active {
  opacity: 1;
  pointer-events: all;
}

.mobile-overlay a {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 6vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  transition: opacity 0.2s ease;
}

.mobile-overlay a:hover {
  opacity: 0.5;
}

/* ── Page Layout ── */

.page-content {
  padding-top: 120px;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--page-padding);
}

.section {
  padding: clamp(60px, 10vw, 140px) 0;
}

/* ── Hero ── */

.hero {
  padding: clamp(40px, 8vw, 100px) 0 clamp(60px, 10vw, 120px);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  max-width: 900px;
}

/* ── Media Showcase ── */

.media-showcase {
  padding: 0 var(--page-padding) clamp(60px, 10vw, 120px);
}

.media-triptych {
  display: grid;
  grid-template-columns: 1fr 1.2fr 0.8fr;
  gap: 20px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

.media-block:nth-child(1) {
  background-color: var(--color-accent-terracotta);
}

.media-block:nth-child(2) {
  background-color: var(--color-accent-sage);
  aspect-ratio: 3 / 4;
}

.media-block:nth-child(3) {
  background-color: var(--color-accent-sand);
}

/* ── Client Marquee ── */

.client-marquee {
  padding: clamp(40px, 8vw, 80px) 0;
  overflow: hidden;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  margin-bottom: 16px;
}

.marquee-track {
  display: flex;
  align-items: center;
  animation: marquee-scroll 30s linear infinite;
}

.marquee-row:nth-child(2) .marquee-track {
  animation-direction: reverse;
  animation-duration: 35s;
}

.marquee-row:nth-child(3) .marquee-track {
  animation-duration: 28s;
}

.marquee-item {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  padding: 0 clamp(16px, 3vw, 40px);
  flex-shrink: 0;
}

.marquee-separator {
  color: var(--color-text-light);
  opacity: 0.4;
  font-size: clamp(1rem, 2vw, 1.5rem);
  padding: 0 clamp(8px, 1.5vw, 20px);
  flex-shrink: 0;
}

@keyframes marquee-scroll {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* ── About ── */

.about-section {
  padding: clamp(80px, 12vw, 160px) 0;
}

.about-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-light);
  margin-bottom: 40px;
}

.about-text {
  max-width: 760px;
}

.about-text p {
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.85;
  margin-bottom: 1.6em;
  color: var(--color-text);
}

.about-text p:last-child {
  margin-bottom: 0;
}

/* ── Founder Letter (Neweno) ── */

.founder-letter {
  max-width: 680px;
  margin: 0 auto;
  padding: clamp(40px, 8vw, 80px) var(--page-padding) clamp(80px, 14vw, 200px);
}

.founder-letter-heading {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: clamp(40px, 6vw, 80px);
}

.founder-letter p {
  font-size: clamp(1.05rem, 1.4vw, 1.15rem);
  line-height: 1.9;
  margin-bottom: 1.8em;
}

.founder-letter p:last-child {
  margin-bottom: 0;
}

.founder-letter .signature {
  margin-top: clamp(40px, 6vw, 80px);
  font-family: var(--font-serif);
  font-style: italic;
  font-size: 1.2rem;
}

/* ── Services ── */

.philosophy-section {
  padding: clamp(40px, 8vw, 80px) 0 clamp(60px, 10vw, 100px);
}

.philosophy-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin-bottom: clamp(30px, 5vw, 60px);
}

.philosophy-text {
  max-width: 720px;
}

.philosophy-text p {
  font-size: clamp(1.05rem, 1.4vw, 1.15rem);
  line-height: 1.85;
  margin-bottom: 1.6em;
}

.divider {
  width: 100%;
  height: 1px;
  background-color: var(--color-border);
}

.services-section {
  padding: clamp(60px, 10vw, 120px) 0 clamp(80px, 14vw, 200px);
}

.services-question {
  font-family: var(--font-serif);
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: clamp(50px, 8vw, 100px);
  max-width: 600px;
}

.service-item {
  max-width: 720px;
  margin-bottom: clamp(40px, 6vw, 70px);
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-name {
  font-family: var(--font-serif);
  font-size: clamp(1.4rem, 2.5vw, 2rem);
  font-weight: 700;
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.service-description {
  font-size: clamp(1rem, 1.3vw, 1.1rem);
  line-height: 1.85;
  color: var(--color-text);
}

/* ── Clients Grid ── */

.clients-heading-section {
  padding: clamp(40px, 8vw, 80px) 0 clamp(20px, 4vw, 40px);
}

.clients-page-title {
  font-family: var(--font-serif);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.clients-page-subtitle {
  font-size: 1rem;
  color: var(--color-text-light);
  margin-top: 12px;
}

.clients-grid-section {
  padding: clamp(30px, 5vw, 60px) 0 clamp(80px, 14vw, 200px);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(30px, 4vw, 60px);
}

.client-card {
  padding-bottom: clamp(20px, 3vw, 40px);
}

.client-name {
  font-family: var(--font-serif);
  font-size: clamp(1.3rem, 2vw, 1.7rem);
  font-weight: 700;
  margin-bottom: 10px;
  letter-spacing: -0.01em;
}

.client-desc {
  font-size: 0.9rem;
  line-height: 1.75;
  color: var(--color-text-light);
}

/* ── Contact ── */

.contact-hero {
  padding: clamp(60px, 15vw, 200px) 0 clamp(40px, 6vw, 80px);
  text-align: center;
}

.contact-title {
  font-family: var(--font-serif);
  font-size: clamp(4rem, 15vw, 14rem);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.04em;
}

.contact-links {
  text-align: center;
  padding: clamp(20px, 4vw, 40px) 0 clamp(80px, 14vw, 200px);
  display: flex;
  justify-content: center;
  gap: clamp(24px, 4vw, 56px);
}

.contact-link {
  font-size: clamp(1rem, 1.5vw, 1.2rem);
  font-weight: 400;
  transition: opacity 0.2s ease;
  border-bottom: 1px solid var(--color-border);
  padding-bottom: 2px;
}

.contact-link:hover {
  opacity: 0.5;
}

/* ── Footer ── */

.site-footer {
  padding: 40px var(--page-padding);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-text {
  font-size: 0.8rem;
  color: var(--color-text-light);
}

/* ── Responsive ── */

@media (max-width: 900px) {
  .desktop-nav {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .media-triptych {
    grid-template-columns: 1fr 1fr;
  }

  .media-block:nth-child(3) {
    display: none;
  }

  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .media-triptych {
    grid-template-columns: 1fr;
  }

  .media-block:nth-child(2),
  .media-block:nth-child(3) {
    display: none;
  }

  .media-block:nth-child(1) {
    aspect-ratio: 16 / 10;
  }

  .clients-grid {
    grid-template-columns: 1fr;
  }

  .contact-links {
    flex-direction: column;
    align-items: center;
    gap: 20px;
  }

  .site-footer {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }
}

