  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-text-light);
  margin-bottom: 40px;
}

.about-text {
  max-width: 760px;
}

.about-text p {
  font-size: clamp(1.05rem, 1.5vw, 1.2rem);
  line-height: 1.85;
  margin-bottom: 1.6em;
  color: var(--color-text);
}

.about-text p:last-child {
  margin-bottom: 0;
}

